mapper.select:
SELECT COUNT(E.EQPMNT_SN) AS TOTAL_NOCS, SUM(CASE WHEN = 'NORMAL' THEN 1 ELSE 0 END) AS NORMAL_NOCS, SUM(CASE WHEN IN ('CAUTION','WARNING') THEN 1 ELSE 0 END) AS CAUTION_NOCS, SUM(CASE WHEN = 'CRITICAL' THEN 1 ELSE 0 END) AS CRITICAL_NOCS, 0 AS OFFLINE_NOCS, SUM(CASE WHEN = 'UNKNOWN' THEN 1 ELSE 0 END) AS UNKNOWN_NOCS, ROUND(AVG(CPU.MSRMT_VL), 1) AS CPU_USGRT, ROUND(AVG(MMRY.MSRMT_VL), 1) AS MMRY_USGRT, CAST(COALESCE(SUM(IFU.MSRMT_VL), 0) AS UNSIGNED) AS IF_USE_NOCS, CAST(COALESCE(SUM(IFT.MSRMT_VL), 0) AS UNSIGNED) AS IF_TOTAL_NOCS FROM eqpmnt_info E LEFT JOIN eqpmnt_stts C ON C.EQPMNT_SN = E.EQPMNT_SN
WHERE E.USE_YN = 'Y' AND E.LINK_SYS_CD = #{linkSysCd} AND E.STN_CD = #{stnCd}
AND (E.EQPMNT_MNG_NO LIKE CONCAT('%', #{searchKeyword}, '%') OR E.EQPMNT_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR E.EQPMNT_IP_ADDR LIKE CONCAT('%', #{searchKeyword}, '%'))
